import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-05-08 :: Ceph Testing meeting","description":"","frontmatter":{"title":"2019-05-08 :: Ceph Testing meeting","date":"2019-05-08T00:00:00.000Z","updated":"2019-05-28T00:00:00.000Z","tags":["Ceph","分布式存储","测试","Rook","Jenkins"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-08_-_-_Ceph_Testing_meeting.md","filePath":"posts/2019/2019-05-08_-_-_Ceph_Testing_meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-05-08_-_-_Ceph_Testing_meeting.md"};function l(r,t,a,g,p,_){return i(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Sebastian, Greg</p><p><strong>会议主题</strong>： Ceph项目进展及视频会议字幕翻译相关事宜</p><p><strong>会议内容</strong>：</p><p><strong>1. Ceph项目进展</strong></p><ul><li><strong>Look into Totality集成</strong>： Greg指出，目前将Look集成到Totality的计划不可行，但从长远来看，这是一个值得考虑的方向。由于Greg正在忙于另一个Rados相关项目，短期内不会继续推进集成工作。</li><li><strong>Rook集成测试</strong>： Sebastian提到，计划通过集成测试将Rook集成到Ceph环境中。他将使用最新的self容器构建，并在Jenkins中运行测试。</li><li><strong>Jenkins集成</strong>： Greg表示，为了在Jenkins中实现Rook测试，需要为Pull Requests构建容器镜像，但目前该功能尚未实现。</li><li><strong>Rook集群</strong>： Sebastian询问是否有可用的Rook集群进行测试，David Galloway等人可能在使用一个Rook集群，但具体位置不明。</li><li><strong>Jenkins运行环境</strong>： Greg不确定Jenkins运行环境是否有权限访问相关基础设施，需要进一步调查。</li></ul><p><strong>2. 视频会议字幕翻译</strong></p><ul><li><strong>字幕翻译</strong>： Sebastian负责英译中的字幕翻译工作。</li><li><strong>测试orchestrator</strong>： Greg询问Sebastian关于某个测试orchestrator的事情，Sebastian表示他将会推进这个项目。</li></ul><p><strong>3. 决定事项</strong></p><ul><li>暂时搁置集成Look into Totality的计划。</li><li>推进Rook集成测试，并在Jenkins中实现。</li><li>调查Rook集群的可用性。</li><li>进一步调查Jenkins运行环境的权限问题。</li><li>Sebastian将继续推进字幕翻译工作。</li></ul><p><strong>4. 后续行动计划</strong></p><ul><li>Greg将调查Rook集群的可用性，并与David Galloway等人联系。</li><li>Greg将调查Jenkins运行环境的权限问题，并尝试解决。</li><li>Sebastian将继续推进Rook集成测试和字幕翻译工作。</li></ul><p><strong>5. 其他事项</strong></p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文关键词，例如： <ul><li>Rados</li><li>systemd</li><li>Rook</li><li>Jenkins</li><li>Pull Requests</li><li>Container</li><li>Terraform</li><li>Vagrant</li></ul></li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的项目名称和术语可能需要根据实际情况进行调整。</li></ul>',17)])])}const d=e(s,[["render",l]]);export{u as __pageData,d as default};
